using System;
using System.Drawing;
using System.IO;
using Aspose.Cells;

// The sample loads an existing XLSX file, creates a conditional formatting rule for the range A1:A10 that sets a LightGreen background when the cell value exceeds 50, and then saves the workbook as a PDF. The conditional formatting is rendered in the resulting PDF, preserving the cell colors.
class Program
{
    static void Main()
    {
        const string inputPath = "input.xlsx";
        const string outputPath = "output.pdf";

        // Verify that the input file exists
        if (!File.Exists(inputPath))
        {
            Console.WriteLine($"Error: Input file \"{inputPath}\" not found.");
            return;
        }

        try
        {
            // Load the source workbook
            Workbook workbook = new Workbook(inputPath);

            // Get the first worksheet
            Worksheet sheet = workbook.Worksheets[0];

            // Define the range for conditional formatting (A1:A10)
            CellArea area = new CellArea
            {
                StartRow = 0,
                EndRow = 9,
                StartColumn = 0,
                EndColumn = 0
            };

            // Add a new conditional formatting collection to the worksheet
            int cfIndex = sheet.ConditionalFormattings.Add();
            FormatConditionCollection fcc = sheet.ConditionalFormattings[cfIndex];
            fcc.AddArea(area);

            // Create a condition: if cell value > 50, change background to LightGreen
            int conditionIndex = fcc.AddCondition(FormatConditionType.CellValue, OperatorType.GreaterThan, "50", null);
            FormatCondition condition = fcc[conditionIndex];

            // Define the style for the condition
            Style style = workbook.CreateStyle();
            style.ForegroundColor = Color.LightGreen;
            style.Pattern = BackgroundType.Solid;
            condition.Style = style;

            // Save the workbook as PDF; the conditional formatting will be reflected in the PDF
            workbook.Save(outputPath, SaveFormat.Pdf);
            Console.WriteLine($"Workbook saved successfully to \"{outputPath}\".");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
